import { useState, useRef, useEffect } from "react";

const VOICE_SYSTEM_PROMPT = `You are Bethany Anne's personal AI content writer for The Luxora Collective. You write growth content that sounds EXACTLY like her — not like an AI, not like a corporate consultant, like a trusted peer who happens to be brilliant at medspa business strategy.

WHO YOU ARE WRITING FOR (Dream Client):
- Independent medspa owner, usually a woman, generating $500K–$3M/year
- She's talented, hardworking, maybe a bit overwhelmed
- She KNOWS she could be doing more but doesn't know exactly what's missing
- She cares deeply about her clients, her team, her brand
- She's probably leaving $200K–$500K on the table in retention, packages, and follow-up
- She is NOT a marketing person — she's a clinician who became a business owner
- She responds to warmth, specificity, and peer energy — not hype, not pressure

BETHANY ANNE'S VOICE RULES:
1. Write like you're talking to a smart friend over coffee — warm, real, direct
2. Start with the feeling, not the feature. Lead with what she's experiencing, not what you offer
3. Use short sentences. Break things up. White space is your friend.
4. No corporate speak. No "synergies," no "leverage," no "robust solutions"
5. No em dashes (—). Use commas, colons, or rewrite the sentence instead
6. Be specific. "$200K in walk-away revenue" hits harder than "significant revenue loss"
7. Permission-based and feminine in energy — never pushy, never bro-ish
8. You can be a little bold, a little wry. Confidence without arrogance.
9. Call her IN, not out. You're pulling her forward, not pointing at what she's doing wrong
10. Reference real medspa scenarios: memberships, Botox retention, package upsells, front desk gaps, no-show patterns, lapsed clients, staff culture

WHAT LUXORA SELLS:
- The 90-Day Growth Engine: installs membership programs, package architecture, upsell frameworks, AI-powered follow-up, staff training, and marketing execution
- For medspas doing $500K–$3M/year
- Financing available via Klarna and Affirm
- Results: more recurring revenue, higher LTV, better client retention, less owner burnout
- Referral partner: Tracy Olson / Aesthetic Injector Academy (injectorsschool.com)

CONTENT FORMATS YOU WRITE:
- Instagram captions (short and punchy, CTA at end, no hashtag blocks unless asked)
- LinkedIn posts (slightly more professional but still warm and real)
- Email subject lines + body (conversational, peer-to-peer energy)
- Facebook group posts (community-first, question or insight format)
- Story/Reel scripts (punchy, scroll-stopping first line, visual direction notes)
- Sales DMs (warm, not spammy, always opens with value or observation)
- Cold outreach emails (lead with local market research angle, not lead gen)
- Discovery call follow-up messages

TONE RULES BY FORMAT:
- Instagram: shorter, emotional, "I see you" energy
- LinkedIn: slightly broader but still medspa-specific and human
- Email: warmest, most personal, like she's writing to one person
- DM: ultra-casual, brief, no pitch in first message
- Reel script: pattern interrupt in line 1, value in 15 seconds, CTA

Always end your content with exactly what was asked. No preamble. No "Here's your caption:" — just deliver the content, clean and ready to use. If you have a brief note (like a suggested hook variant), put it after the main content in italics, clearly separated.`;

const CONTENT_TYPES = [
  { id: "instagram", label: "Instagram Caption", emoji: "📸" },
  { id: "linkedin", label: "LinkedIn Post", emoji: "💼" },
  { id: "email", label: "Email", emoji: "✉️" },
  { id: "dm", label: "Sales DM", emoji: "💬" },
  { id: "reel", label: "Reel Script", emoji: "🎬" },
  { id: "story", label: "Story Script", emoji: "📱" },
  { id: "facebook", label: "Facebook Post", emoji: "👥" },
  { id: "followup", label: "Follow-Up Message", emoji: "🔄" },
];

const QUICK_PROMPTS = [
  "Write about why memberships are the most underused revenue tool in medspas",
  "A post about the moment an owner realizes her front desk is leaking revenue",
  "Email to a medspa owner who went quiet after a discovery call",
  "Reel script: 3 signs your medspa is leaving $200K on the table",
  "LinkedIn post about the difference between busy and profitable",
  "DM to a medspa owner who just posted about hitting burnout",
  "Caption for a before/after of a medspa business transformation",
  "Email subject lines for a cold outreach sequence (give me 5)",
];

export default function LuxoraAIStudio() {
  const [selectedType, setSelectedType] = useState("instagram");
  const [prompt, setPrompt] = useState("");
  const [output, setOutput] = useState("");
  const [loading, setLoading] = useState(false);
  const [copied, setCopied] = useState(false);
  const [history, setHistory] = useState([]);
  const [activeTab, setActiveTab] = useState("create");
  const [additionalContext, setAdditionalContext] = useState("");
  const [showContext, setShowContext] = useState(false);
  const outputRef = useRef(null);
  const textareaRef = useRef(null);

  const selectedTypeObj = CONTENT_TYPES.find(t => t.id === selectedType);

  const generateContent = async (customPrompt) => {
    const finalPrompt = customPrompt || prompt;
    if (!finalPrompt.trim()) return;

    setLoading(true);
    setOutput("");
    setActiveTab("create");

    const userMessage = `Content type: ${selectedTypeObj.label}
Topic/Prompt: ${finalPrompt}${additionalContext ? `\nAdditional context: ${additionalContext}` : ""}

Write this now, ready to use.`;

    try {
      const response = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          model: "claude-sonnet-4-20250514",
          max_tokens: 1000,
          system: VOICE_SYSTEM_PROMPT,
          messages: [{ role: "user", content: userMessage }],
        }),
      });

      const data = await response.json();
      const result = data.content?.[0]?.text || "Something went wrong. Try again.";
      setOutput(result);

      setHistory(prev => [{
        type: selectedTypeObj.label,
        emoji: selectedTypeObj.emoji,
        prompt: finalPrompt,
        output: result,
        timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      }, ...prev.slice(0, 9)]);

    } catch (err) {
      setOutput("Connection error. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const handleCopy = () => {
    navigator.clipboard.writeText(output);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleQuickPrompt = (p) => {
    setPrompt(p);
    setTimeout(() => generateContent(p), 100);
  };

  useEffect(() => {
    if (output && outputRef.current) {
      outputRef.current.scrollIntoView({ behavior: "smooth", block: "nearest" });
    }
  }, [output]);

  return (
    <div style={{
      fontFamily: "'Cormorant Garamond', Georgia, serif",
      minHeight: "100vh",
      background: "linear-gradient(135deg, #0a0a0f 0%, #12101a 40%, #0d0a14 100%)",
      color: "#f0ece4",
      padding: "0",
    }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,300;0,400;0,500;0,600;1,300;1,400&family=Montserrat:wght@300;400;500;600&display=swap');

        * { box-sizing: border-box; }

        ::-webkit-scrollbar { width: 4px; }
        ::-webkit-scrollbar-track { background: transparent; }
        ::-webkit-scrollbar-thumb { background: #b8967a44; border-radius: 2px; }

        .fade-in { animation: fadeIn 0.5s ease forwards; }
        @keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

        .shimmer {
          background: linear-gradient(90deg, #1e1a28 25%, #2a2438 50%, #1e1a28 75%);
          background-size: 200% 100%;
          animation: shimmer 1.5s infinite;
          border-radius: 4px;
        }
        @keyframes shimmer { 0% { background-position: 200% 0; } 100% { background-position: -200% 0; } }

        .type-btn {
          background: transparent;
          border: 1px solid #2a2438;
          border-radius: 6px;
          color: #8a7a9a;
          padding: 8px 12px;
          font-family: 'Montserrat', sans-serif;
          font-size: 11px;
          font-weight: 500;
          letter-spacing: 0.05em;
          cursor: pointer;
          transition: all 0.2s;
          white-space: nowrap;
        }
        .type-btn:hover { border-color: #b8967a55; color: #c8b4a4; }
        .type-btn.active {
          background: linear-gradient(135deg, #b8967a22, #d4a87422);
          border-color: #b8967a;
          color: #e8c8a8;
        }

        .main-btn {
          background: linear-gradient(135deg, #b8967a, #d4a874);
          border: none;
          border-radius: 8px;
          color: #0a0a0f;
          padding: 14px 28px;
          font-family: 'Montserrat', sans-serif;
          font-size: 12px;
          font-weight: 600;
          letter-spacing: 0.12em;
          text-transform: uppercase;
          cursor: pointer;
          transition: all 0.2s;
          width: 100%;
        }
        .main-btn:hover { transform: translateY(-1px); box-shadow: 0 8px 24px #b8967a44; }
        .main-btn:disabled { opacity: 0.5; cursor: not-allowed; transform: none; }

        .ghost-btn {
          background: transparent;
          border: 1px solid #2a2438;
          border-radius: 6px;
          color: #8a7a9a;
          padding: 8px 16px;
          font-family: 'Montserrat', sans-serif;
          font-size: 11px;
          font-weight: 500;
          letter-spacing: 0.08em;
          cursor: pointer;
          transition: all 0.2s;
        }
        .ghost-btn:hover { border-color: #b8967a55; color: #c8b4a4; }

        textarea, .output-box {
          font-family: 'Montserrat', sans-serif;
          font-size: 13px;
          font-weight: 300;
          line-height: 1.7;
          color: #d8cfc4;
        }

        .quick-tag {
          background: #1a1624;
          border: 1px solid #2a2438;
          border-radius: 20px;
          color: #8a7a9a;
          padding: 6px 14px;
          font-family: 'Montserrat', sans-serif;
          font-size: 11px;
          font-weight: 400;
          cursor: pointer;
          transition: all 0.2s;
          white-space: nowrap;
        }
        .quick-tag:hover { border-color: #b8967a66; color: #c8b4a4; background: #1e1a2a; }

        .tab-btn {
          background: transparent;
          border: none;
          border-bottom: 2px solid transparent;
          color: #5a5068;
          padding: 10px 20px;
          font-family: 'Montserrat', sans-serif;
          font-size: 11px;
          font-weight: 500;
          letter-spacing: 0.1em;
          text-transform: uppercase;
          cursor: pointer;
          transition: all 0.2s;
        }
        .tab-btn.active { color: #b8967a; border-bottom-color: #b8967a; }
        .tab-btn:hover:not(.active) { color: #8a7a9a; }

        .history-card {
          background: #1a1624;
          border: 1px solid #2a2438;
          border-radius: 8px;
          padding: 14px 16px;
          cursor: pointer;
          transition: all 0.2s;
          margin-bottom: 10px;
        }
        .history-card:hover { border-color: #b8967a44; }

        .copy-btn {
          background: #1e1a28;
          border: 1px solid #2a2438;
          border-radius: 6px;
          color: #8a7a9a;
          padding: 8px 16px;
          font-family: 'Montserrat', sans-serif;
          font-size: 11px;
          font-weight: 500;
          letter-spacing: 0.08em;
          cursor: pointer;
          transition: all 0.2s;
        }
        .copy-btn:hover { border-color: #b8967a66; color: #c8b4a4; }
        .copy-btn.copied { border-color: #7ab87a; color: #a8d4a8; }

        .pulse { animation: pulse 2s ease-in-out infinite; }
        @keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.5; } }

        .context-toggle {
          background: transparent;
          border: none;
          color: #5a5068;
          font-family: 'Montserrat', sans-serif;
          font-size: 11px;
          font-weight: 400;
          cursor: pointer;
          padding: 4px 0;
          transition: color 0.2s;
          text-decoration: underline;
          text-underline-offset: 3px;
        }
        .context-toggle:hover { color: #b8967a; }
      `}</style>

      {/* Header */}
      <div style={{
        borderBottom: "1px solid #1e1a28",
        padding: "24px 32px",
        display: "flex",
        alignItems: "center",
        justifyContent: "space-between",
        position: "sticky",
        top: 0,
        background: "rgba(10,10,15,0.95)",
        backdropFilter: "blur(12px)",
        zIndex: 100,
      }}>
        <div>
          <div style={{
            fontFamily: "'Cormorant Garamond', serif",
            fontSize: "22px",
            fontWeight: 300,
            letterSpacing: "0.15em",
            color: "#e8d8c8",
          }}>
            THE LUXORA COLLECTIVE
          </div>
          <div style={{
            fontFamily: "'Montserrat', sans-serif",
            fontSize: "10px",
            fontWeight: 500,
            letterSpacing: "0.25em",
            color: "#b8967a",
            textTransform: "uppercase",
            marginTop: "2px",
          }}>
            AI Content Studio · Bethany Anne
          </div>
        </div>
        <div style={{
          width: "8px",
          height: "8px",
          borderRadius: "50%",
          background: "#7ab87a",
          boxShadow: "0 0 8px #7ab87a88",
        }} className="pulse" title="AI Ready" />
      </div>

      <div style={{ maxWidth: "900px", margin: "0 auto", padding: "32px 24px" }}>

        {/* Tabs */}
        <div style={{ borderBottom: "1px solid #1e1a28", marginBottom: "28px", display: "flex" }}>
          <button className={`tab-btn ${activeTab === 'create' ? 'active' : ''}`} onClick={() => setActiveTab('create')}>Create</button>
          <button className={`tab-btn ${activeTab === 'history' ? 'active' : ''}`} onClick={() => setActiveTab('history')}>
            History {history.length > 0 && `(${history.length})`}
          </button>
          <button className={`tab-btn ${activeTab === 'voice' ? 'active' : ''}`} onClick={() => setActiveTab('voice')}>Your Voice Guide</button>
        </div>

        {/* CREATE TAB */}
        {activeTab === 'create' && (
          <div className="fade-in">
            {/* Content Type Selector */}
            <div style={{ marginBottom: "24px" }}>
              <div style={{
                fontFamily: "'Montserrat', sans-serif",
                fontSize: "10px",
                fontWeight: 600,
                letterSpacing: "0.2em",
                color: "#5a5068",
                textTransform: "uppercase",
                marginBottom: "12px",
              }}>Content Format</div>
              <div style={{ display: "flex", flexWrap: "wrap", gap: "8px" }}>
                {CONTENT_TYPES.map(t => (
                  <button
                    key={t.id}
                    className={`type-btn ${selectedType === t.id ? 'active' : ''}`}
                    onClick={() => setSelectedType(t.id)}
                  >
                    {t.emoji} {t.label}
                  </button>
                ))}
              </div>
            </div>

            {/* Prompt Input */}
            <div style={{ marginBottom: "16px" }}>
              <div style={{
                fontFamily: "'Montserrat', sans-serif",
                fontSize: "10px",
                fontWeight: 600,
                letterSpacing: "0.2em",
                color: "#5a5068",
                textTransform: "uppercase",
                marginBottom: "12px",
              }}>What do you want to write about?</div>
              <textarea
                ref={textareaRef}
                value={prompt}
                onChange={e => setPrompt(e.target.value)}
                onKeyDown={e => {
                  if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) generateContent();
                }}
                placeholder={`Write a ${selectedTypeObj?.label.toLowerCase()} about...`}
                rows={3}
                style={{
                  width: "100%",
                  background: "#12101a",
                  border: "1px solid #2a2438",
                  borderRadius: "8px",
                  padding: "14px 16px",
                  color: "#d8cfc4",
                  resize: "none",
                  outline: "none",
                  transition: "border-color 0.2s",
                  fontFamily: "'Montserrat', sans-serif",
                  fontSize: "13px",
                  fontWeight: 300,
                  lineHeight: 1.7,
                }}
                onFocus={e => e.target.style.borderColor = "#b8967a66"}
                onBlur={e => e.target.style.borderColor = "#2a2438"}
              />
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: "6px" }}>
                <button className="context-toggle" onClick={() => setShowContext(!showContext)}>
                  {showContext ? "Hide" : "+ Add"} additional context
                </button>
                <div style={{
                  fontFamily: "'Montserrat', sans-serif",
                  fontSize: "10px",
                  color: "#3a3248",
                  letterSpacing: "0.05em",
                }}>⌘ + Enter to generate</div>
              </div>
            </div>

            {/* Additional Context */}
            {showContext && (
              <div style={{ marginBottom: "16px" }} className="fade-in">
                <textarea
                  value={additionalContext}
                  onChange={e => setAdditionalContext(e.target.value)}
                  placeholder="e.g. This is for a medspa in Dallas, she just launched a new membership tier, tone should be celebratory..."
                  rows={2}
                  style={{
                    width: "100%",
                    background: "#0e0c16",
                    border: "1px solid #1e1a28",
                    borderRadius: "8px",
                    padding: "12px 16px",
                    color: "#a89898",
                    resize: "none",
                    outline: "none",
                    fontFamily: "'Montserrat', sans-serif",
                    fontSize: "12px",
                    fontWeight: 300,
                    lineHeight: 1.6,
                  }}
                />
              </div>
            )}

            {/* Generate Button */}
            <button
              className="main-btn"
              onClick={() => generateContent()}
              disabled={loading || !prompt.trim()}
            >
              {loading ? "Writing in your voice..." : `Generate ${selectedTypeObj?.label}`}
            </button>

            {/* Quick Prompts */}
            <div style={{ marginTop: "28px" }}>
              <div style={{
                fontFamily: "'Montserrat', sans-serif",
                fontSize: "10px",
                fontWeight: 600,
                letterSpacing: "0.2em",
                color: "#3a3248",
                textTransform: "uppercase",
                marginBottom: "12px",
              }}>Quick Start</div>
              <div style={{ display: "flex", flexWrap: "wrap", gap: "8px" }}>
                {QUICK_PROMPTS.map((p, i) => (
                  <button key={i} className="quick-tag" onClick={() => handleQuickPrompt(p)}>
                    {p.length > 48 ? p.slice(0, 48) + "..." : p}
                  </button>
                ))}
              </div>
            </div>

            {/* Output */}
            {(loading || output) && (
              <div ref={outputRef} style={{ marginTop: "32px" }} className="fade-in">
                <div style={{
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "space-between",
                  marginBottom: "12px",
                }}>
                  <div style={{
                    fontFamily: "'Montserrat', sans-serif",
                    fontSize: "10px",
                    fontWeight: 600,
                    letterSpacing: "0.2em",
                    color: "#b8967a",
                    textTransform: "uppercase",
                  }}>
                    {selectedTypeObj?.emoji} {selectedTypeObj?.label} · Ready to use
                  </div>
                  {output && !loading && (
                    <div style={{ display: "flex", gap: "8px" }}>
                      <button
                        className={`copy-btn ${copied ? 'copied' : ''}`}
                        onClick={handleCopy}
                      >
                        {copied ? "✓ Copied" : "Copy"}
                      </button>
                      <button className="ghost-btn" onClick={() => generateContent()}>
                        Regenerate
                      </button>
                    </div>
                  )}
                </div>

                <div style={{
                  background: "#12101a",
                  border: "1px solid #2a2438",
                  borderRadius: "10px",
                  padding: "24px",
                  minHeight: "120px",
                  position: "relative",
                  overflow: "hidden",
                }}>
                  {/* Accent line */}
                  <div style={{
                    position: "absolute",
                    left: 0,
                    top: 0,
                    bottom: 0,
                    width: "2px",
                    background: "linear-gradient(180deg, #b8967a, transparent)",
                    borderRadius: "10px 0 0 10px",
                  }} />

                  {loading ? (
                    <div>
                      <div className="shimmer" style={{ height: "14px", width: "85%", marginBottom: "10px" }} />
                      <div className="shimmer" style={{ height: "14px", width: "70%", marginBottom: "10px" }} />
                      <div className="shimmer" style={{ height: "14px", width: "90%", marginBottom: "10px" }} />
                      <div className="shimmer" style={{ height: "14px", width: "60%", marginBottom: "10px" }} />
                      <div className="shimmer" style={{ height: "14px", width: "75%", marginBottom: "10px" }} />
                      <div style={{
                        fontFamily: "'Montserrat', sans-serif",
                        fontSize: "11px",
                        color: "#5a5068",
                        marginTop: "16px",
                        letterSpacing: "0.05em",
                      }}>Writing in your voice...</div>
                    </div>
                  ) : (
                    <div
                      className="output-box"
                      style={{
                        whiteSpace: "pre-wrap",
                        paddingLeft: "12px",
                        lineHeight: 1.8,
                      }}
                    >
                      {output}
                    </div>
                  )}
                </div>
              </div>
            )}
          </div>
        )}

        {/* HISTORY TAB */}
        {activeTab === 'history' && (
          <div className="fade-in">
            {history.length === 0 ? (
              <div style={{
                textAlign: "center",
                padding: "60px 20px",
                color: "#3a3248",
                fontFamily: "'Montserrat', sans-serif",
                fontSize: "13px",
              }}>
                Your generated content will appear here
              </div>
            ) : (
              history.map((item, i) => (
                <div key={i} className="history-card" onClick={() => {
                  setOutput(item.output);
                  setPrompt(item.prompt);
                  setSelectedType(CONTENT_TYPES.find(t => t.label === item.type)?.id || "instagram");
                  setActiveTab('create');
                }}>
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "6px" }}>
                    <span style={{
                      fontFamily: "'Montserrat', sans-serif",
                      fontSize: "10px",
                      fontWeight: 600,
                      letterSpacing: "0.15em",
                      color: "#b8967a",
                      textTransform: "uppercase",
                    }}>{item.emoji} {item.type}</span>
                    <span style={{
                      fontFamily: "'Montserrat', sans-serif",
                      fontSize: "10px",
                      color: "#3a3248",
                    }}>{item.timestamp}</span>
                  </div>
                  <div style={{
                    fontFamily: "'Montserrat', sans-serif",
                    fontSize: "12px",
                    color: "#8a7a9a",
                    overflow: "hidden",
                    textOverflow: "ellipsis",
                    whiteSpace: "nowrap",
                  }}>{item.prompt}</div>
                  <div style={{
                    fontFamily: "'Montserrat', sans-serif",
                    fontSize: "11px",
                    color: "#4a4058",
                    marginTop: "6px",
                    overflow: "hidden",
                    display: "-webkit-box",
                    WebkitLineClamp: 2,
                    WebkitBoxOrient: "vertical",
                    lineHeight: 1.5,
                  }}>{item.output.slice(0, 120)}...</div>
                </div>
              ))
            )}
          </div>
        )}

        {/* VOICE GUIDE TAB */}
        {activeTab === 'voice' && (
          <div className="fade-in">
            <div style={{
              fontFamily: "'Cormorant Garamond', serif",
              fontSize: "28px",
              fontWeight: 300,
              letterSpacing: "0.05em",
              color: "#e8d8c8",
              marginBottom: "8px",
            }}>Your Voice, Codified</div>
            <div style={{
              fontFamily: "'Montserrat', sans-serif",
              fontSize: "12px",
              color: "#5a5068",
              marginBottom: "28px",
              lineHeight: 1.6,
            }}>This AI has been trained on your specific voice, your dream client, and your brand. Here's what it knows.</div>

            {[
              {
                title: "Your Dream Client",
                content: "Independent medspa owner, $500K to $3M/year. She's talented, hardworking, and probably leaving $200K+ on the table in retention, memberships, and package upsells. She's a clinician who became a business owner. She responds to warmth, specificity, and peer energy. Not hype, not pressure."
              },
              {
