          font-weight: 500;
          letter-spacing: 0.05em;
          cursor: pointer;
          transition: all 0.2s;
          white-space: nowrap;
        }
        .type-btn:hover { border-color: #b8967a55; color: #c8b4a4; }
        .type-btn.active {
