function SwipeCard({ item, generateContent, setPrompt, setSelectedType, setActiveTab }) {
  const [expanded, setExpanded] = useState(false);
  const [swipeCopied, setSwipeCopied] = useState(false);

  const handleGenerate = () => {
    setPrompt(item.promptToGenerate);
    setSelectedType("instagram");
    setActiveTab("create");
    setTimeout(() => generateContent(item.promptToGenerate), 150);
  };

  return (
    <div style={{ background: "#12101a", border: "1px solid #2a2438", borderRadius: "10px", marginBottom: "16px", overflow: "hidden" }}>
      <div style={{ padding: "18px 20px", borderBottom: expanded ? "1px solid #1e1a28" : "none", cursor: "pointer" }} onClick={() => setExpanded(!expanded)}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
          <div>
            <div style={{ fontFamily: "'Montserrat', sans-serif", fontSize: "11px", fontWeight: 600, letterSpacing: "0.15em", color: "#b8967a", textTransform: "uppercase", marginBottom: "4px" }}>{item.format}</div>
            <div style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: "18px", fontWeight: 400, color: "#e8d8c8" }}>{item.label}</div>
          </div>
          <div style={{ fontFamily: "'Montserrat', sans-serif", fontSize: "16px", color: "#5a5068", marginTop: "4px" }}>{expanded ? "↑" : "↓"}</div>
        </div>
        <div style={{ fontFamily: "'Montserrat', sans-serif", fontSize: "11px", color: "#5a5068", marginTop: "8px", lineHeight: 1.6, fontWeight: 300 }}>{item.note}</div>
      </div>
      {expanded && (
        <div>
          <div style={{ padding: "20px", borderBottom: "1px solid #1e1a28", position: "relative" }}>
            <div style={{ position: "absolute", left: 0, top: 0, bottom: 0, width: "2px", background: "linear-gradient(180deg, #b8967a, transparent)" }} />
            <div style={{ fontFamily: "'Montserrat', sans-serif", fontSize: "12px", fontWeight: 300, color: "#c8bfb4", whiteSpace: "pre-wrap", lineHeight: 1.8, paddingLeft: "12px" }}>{item.content}</div>
          </div>
          <div style={{ padding: "14px 20px", display: "flex", gap: "10px", flexWrap: "wrap" }}>
            <button className={"copy-btn" + (swipeCopied ? " copied" : "")} onClick={() => { navigator.clipboard.writeText(item.content); setSwipeCopied(true); setTimeout(() => setSwipeCopied(false), 2000); }}>
              {swipeCopied ? "✓ Copied" : "Copy Post"}
            </button>
