export default function LuxoraAIStudio() {
  const [selectedType, setSelectedType] = useState("instagram");
  const [prompt, setPrompt] = useState("");
  const [output, setOutput] = useState("");
  const [loading, setLoading] = useState(false);
  const [copied, setCopied] = useState(false);
  const [history, setHistory] = useState([]);
  const [activeTab, setActiveTab] = useState("create");
  const [additionalContext, setAdditionalContext] = useState("");
  const [showContext, setShowContext] = useState(false);
  const outputRef = useRef(null);

  const selectedTypeObj = CONTENT_TYPES.find(t => t.id === selectedType);

  const generateContent = async (customPrompt) => {
    const finalPrompt = customPrompt || prompt;
    if (!finalPrompt.trim()) return;
    setLoading(true);
    setOutput("");
    setActiveTab("create");
    const userMessage = "Content type: " + selectedTypeObj.label + "\nTopic/Prompt: " + finalPrompt + (additionalContext ? "\nAdditional context: " + additionalContext : "") + "\n\nWrite this now, ready to use.";
    try {
      const response = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          model: "claude-sonnet-4-20250514",
          max_tokens: 1000,
          system: VOICE_SYSTEM_PROMPT,
          messages: [{ role: "user", content: userMessage }],
        }),
      });
      const data = await response.json();
      const result = (data.content && data.content[0] && data.content[0].text) ? data.content[0].text : "Something went wrong. Try again.";
      setOutput(result);
      setHistory(prev => [{ type: selectedTypeObj.label, emoji: selectedTypeObj.emoji, prompt: finalPrompt, output: result, timestamp: new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }) }, ...prev.slice(0, 9)]);
    } catch (err) {
      setOutput("Connection error. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const handleCopy = () => {
    navigator.clipboard.writeText(output);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleQuickPrompt = (p) => {
    setPrompt(p);
    setTimeout(() => generateContent(p), 100);
  };

  useEffect(() => {
    if (output && outputRef.current) {
      outputRef.current.scrollIntoView({ behavior: "smooth", block: "nearest" });
    }
  }, [output]);

  return (
    <div style={{ fontFamily: "'Cormorant Garamond', Georgia, serif", minHeight: "100vh", background: "linear-gradient(135deg, #0a0a0f 0%, #12101a 40%, #0d0a14 100%)", color: "#f0ece4" }}>
      <style>{styles}</style>

      {/* Header */}
      <div style={{ borderBottom: "1px solid #1e1a28", padding: "24px 32px", display: "flex", alignItems: "center", justifyContent: "space-between", position: "sticky", top: 0, background: "rgba(10,10,15,0.95)", backdropFilter: "blur(12px)", zIndex: 100 }}>
        <div>
          <div style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: "22px", fontWeight: 300, letterSpacing: "0.15em", color: "#e8d8c8" }}>THE LUXORA COLLECTIVE</div>
          <div style={{ fontFamily: "'Montserrat', sans-serif", fontSize: "10px", fontWeight: 500, letterSpacing: "0.25em", color: "#b8967a", textTransform: "uppercase", marginTop: "2px" }}>AI Content Studio · Bethany Anne</div>
        </div>
        <div style={{ width: "8px", height: "8px", borderRadius: "50%", background: "#7ab87a", boxShadow: "0 0 8px #7ab87a88" }} className="pulse" />
      </div>

      <div style={{ maxWidth: "900px", margin: "0 auto", padding: "32px 24px" }}>

        {/* Tabs */}
        <div style={{ borderBottom: "1px solid #1e1a28", marginBottom: "28px", display: "flex", flexWrap: "wrap" }}>
          <button className={"tab-btn" + (activeTab === "create" ? " active" : "")} onClick={() => setActiveTab("create")}>Create</button>
          <button className={"tab-btn" + (activeTab === "history" ? " active" : "")} onClick={() => setActiveTab("history")}>History {history.length > 0 ? "(" + history.length + ")" : ""}</button>
          <button className={"tab-btn" + (activeTab === "swipe" ? " active" : "")} onClick={() => setActiveTab("swipe")}>Swipe File</button>
          <button className={"tab-btn" + (activeTab === "voice" ? " active" : "")} onClick={() => setActiveTab("voice")}>Voice Guide</button>
        </div>

        {/* CREATE TAB */}
        {activeTab === "create" && (
          <div className="fade-in">
            <div style={{ marginBottom: "24px" }}>
              <div style={{ fontFamily: "'Montserrat', sans-serif", fontSize: "10px", fontWeight: 600, letterSpacing: "0.2em", color: "#5a5068", textTransform: "uppercase", marginBottom: "12px" }}>Content Format</div>
              <div style={{ display: "flex", flexWrap: "wrap", gap: "8px" }}>
                {CONTENT_TYPES.map(t => (
                  <button key={t.id} className={"type-btn" + (selectedType === t.id ? " active" : "")} onClick={() => setSelectedType(t.id)}>{t.emoji} {t.label}</button>
                ))}
              </div>
            </div>

            <div style={{ marginBottom: "16px" }}>
              <div style={{ fontFamily: "'Montserrat', sans-serif", fontSize: "10px", fontWeight: 600, letterSpacing: "0.2em", color: "#5a5068", textTransform: "uppercase", marginBottom: "12px" }}>What do you want to write about?</div>
              <textarea
                value={prompt}
                onChange={e => setPrompt(e.target.value)}
                onKeyDown={e => { if (e.key === "Enter" && (e.metaKey || e.ctrlKey)) generateContent(); }}
                placeholder={"Write a " + (selectedTypeObj ? selectedTypeObj.label.toLowerCase() : "") + " about..."}
                rows={3}
                style={{ width: "100%", background: "#12101a", border: "1px solid #2a2438", borderRadius: "8px", padding: "14px 16px", color: "#d8cfc4", resize: "none", outline: "none", fontFamily: "'Montserrat', sans-serif", fontSize: "13px", fontWeight: 300, lineHeight: 1.7 }}
                onFocus={e => { e.target.style.borderColor = "#b8967a66"; }}
                onBlur={e => { e.target.style.borderColor = "#2a2438"; }}
              />
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: "6px" }}>
                <button style={{ background: "transparent", border: "none", color: "#5a5068", fontFamily: "'Montserrat', sans-serif", fontSize: "11px", cursor: "pointer", textDecoration: "underline", textUnderlineOffset: "3px", padding: "4px 0" }} onClick={() => setShowContext(!showContext)}>
                  {showContext ? "Hide" : "+ Add"} context
                </button>
                <div style={{ fontFamily: "'Montserrat', sans-serif", fontSize: "10px", color: "#3a3248", letterSpacing: "0.05em" }}>Cmd + Enter to generate</div>
              </div>
            </div>

            {showContext && (
              <div style={{ marginBottom: "16px" }} className="fade-in">
                <textarea
                  value={additionalContext}
                  onChange={e => setAdditionalContext(e.target.value)}
                  placeholder="e.g. This is for a medspa in Dallas, she just launched a new membership tier, tone should be celebratory..."
                  rows={2}
                  style={{ width: "100%", background: "#0e0c16", border: "1px solid #1e1a28", borderRadius: "8px", padding: "12px 16px", color: "#a89898", resize: "none", outline: "none", fontFamily: "'Montserrat', sans-serif", fontSize: "12px", fontWeight: 300, lineHeight: 1.6 }}
                />
              </div>
            )}

            <button className="main-btn" onClick={() => generateContent()} disabled={loading || !prompt.trim()}>
              {loading ? "Writing in your voice..." : "Generate " + (selectedTypeObj ? selectedTypeObj.label : "")}
            </button>

            <div style={{ marginTop: "28px" }}>
              <div style={{ fontFamily: "'Montserrat', sans-serif", fontSize: "10px", fontWeight: 600, letterSpacing: "0.2em", color: "#3a3248", textTransform: "uppercase", marginBottom: "12px" }}>Quick Start</div>
