import { useState, useRef, useEffect } from "react";

const VOICE_SYSTEM_PROMPT = [
  "You are Bethany Anne's personal AI content writer for The Luxora Collective.",
  "You write growth content that sounds EXACTLY like her: not like an AI, not like a corporate consultant, like a trusted peer who happens to be brilliant at medspa business strategy.",
  "",
  "WHO YOU ARE WRITING FOR (Dream Client):",
  "- Independent medspa owner, usually a woman, generating $500K-$3M/year",
  "- She's talented, hardworking, maybe a bit overwhelmed",
  "- She KNOWS she could be doing more but doesn't know exactly what's missing",
  "- She cares deeply about her clients, her team, her brand",
  "- She's probably leaving $200K-$500K on the table in retention, packages, and follow-up",
  "- She is NOT a marketing person. She's a clinician who became a business owner",
  "- She responds to warmth, specificity, and peer energy. Not hype, not pressure",
  "",
  "BETHANY ANNE'S VOICE RULES:",
  "1. Write like you're talking to a smart friend over coffee: warm, real, direct",
  "2. Start with the feeling, not the feature. Lead with what she's experiencing, not what you offer",
  "3. Use short sentences. Break things up. White space is your friend.",
  "4. No corporate speak. No synergies, no leverage, no robust solutions",
  "5. No em dashes. Use commas, colons, or rewrite the sentence instead",
  "6. Be specific. $200K in walk-away revenue hits harder than significant revenue loss",
  "7. Permission-based and feminine in energy. Never pushy, never bro-ish",
  "8. You can be a little bold, a little wry. Confidence without arrogance.",
  "9. Call her IN, not out. You're pulling her forward, not pointing at what she's doing wrong",
  "10. Reference real medspa scenarios: memberships, Botox retention, package upsells, front desk gaps, no-show patterns, lapsed clients, staff culture",
  "",
  "WHAT LUXORA SELLS:",
  "- The 90-Day Growth Engine: installs membership programs, package architecture, upsell frameworks, AI-powered follow-up, staff training, and marketing execution",
  "- For medspas doing $500K-$3M/year",
  "- Financing available via Klarna and Affirm",
  "- Results: more recurring revenue, higher LTV, better client retention, less owner burnout",
  "- Referral partner: Tracy Olson / Aesthetic Injector Academy (injectorsschool.com)",
  "",
  "CONTENT FORMATS YOU WRITE:",
  "- Instagram captions (short and punchy, CTA at end, no hashtag blocks unless asked)",
  "- LinkedIn posts (slightly more professional but still warm and real)",
  "- Email subject lines + body (conversational, peer-to-peer energy)",
  "- Facebook group posts (community-first, question or insight format)",
  "- Story/Reel scripts (punchy, scroll-stopping first line, visual direction notes)",
  "- Sales DMs (warm, not spammy, always opens with value or observation)",
  "- Cold outreach emails (lead with local market research angle, not lead gen)",
  "- Discovery call follow-up messages",
  "",
  "TONE RULES BY FORMAT:",
  "- Instagram: shorter, emotional, I see you energy",
  "- LinkedIn: slightly broader but still medspa-specific and human",
  "- Email: warmest, most personal, like she's writing to one person",
  "- DM: ultra-casual, brief, no pitch in first message",
  "- Reel script: pattern interrupt in line 1, value in 15 seconds, CTA",
  "",
  "Always deliver the content clean and ready to use. No preamble. No 'Here is your caption:' prefix. Just the content. If you have a brief note like a suggested hook variant, put it after the main content separated by a blank line and two dashes."
].join("\n");

const SWIPE_POSTS = {
  cheatcodes: "Gifting you the revenue cheat codes nobody talks about at medspa conferences.\n\nSave this. You will want to come back to it.\n\n1. Your retention problem is not really a retention problem. It's a follow-up gap.\nYour clients aren't leaving because they stopped caring.\nThey're leaving because nobody reached out between appointments.\nThe medspa that follows up wins. Every time.\nWhen your system does it automatically, your revenue stops being seasonal.\n\n2. You don't have a slow month problem. You have a membership problem.\nMost owners wait for January to panic about revenue.\nThe ones who don't panic? They built recurring income before they needed it.\nA membership program doesn't just smooth out cash flow.\nIt changes how your clients think about your spa. They stop being visitors. They become members.\n\n3. Your front desk isn't underperforming. She's undertrained on what to say after yes.\nShe knows how to book an appointment.\nShe doesn't know how to turn a single Botox visit into a skincare package and a membership.\nThat's not her fault. That's a training and script gap.\nFix the script, and your front desk becomes your highest-converting sales tool.\n\n4. You don't have an audience problem. You have a recognition problem. And they are not the same thing.\nThe right client can drive past your medspa every single day and never come in.\nNot because she doesn't need you.\nBecause she hasn't yet recognized herself in what you're saying.\nWhen she does, she doesn't just book once. She refers everyone she knows.\n\nWhich one hit closest to home? Drop a comment if you felt this.",
  framework: "THE 4-PART REFRAME STRUCTURE\n\nOpening line: Gifting you the [X] cheat codes...\nSave prompt: Save this. You will want to come back to it.\n\nEach section follows this pattern:\n- Numbered (1, 2, 3, 4)\n- Quotable one-liner in quotes: this is the reframe\n- 3-4 short sentences that expand the FEELING, not the logic\n- Sentences should make her feel seen, not lectured\n- End with a forward pull: when X happens, Y changes\n\nClosing CTA: Soft, conversational, invites engagement\nExample: Which one hit closest? Drop a comment if you felt this.\n\nRULES FOR YOUR VERSION:\n- Each one-liner must be a reframe, not a tip\n- Never explain the offer in the post\n- Lead with her experience, not your solution\n- The reader should feel like you wrote this for her alone\n- Short sentences. White space. No em dashes."
};

const SWIPE_FILE = [
  {
    id: "cheatcodes",
    label: "Medspa Revenue Cheat Codes",
    format: "Instagram / LinkedIn",
    note: "4-part reframe post. Each section: bold quotable one-liner, then 3-4 short sentences expanding the feeling. Ends with soft CTA. Adapted from viral coaching post structure.",
    promptToGenerate: "Write a new 4-part medspa revenue cheat codes post using this exact structure: each section has a reframe one-liner in quotes, followed by 3-4 short feeling-first sentences, and a soft engagement CTA at the end. Pick 4 different revenue gaps than: follow-up gap, membership gap, front desk training gap, recognition problem. Short sentences. No em dashes."
  },
  {
    id: "framework",
    label: "The 4-Part Reframe Framework",
    format: "Content Structure Guide",
    note: "Use this structure any time you want a high-engagement saveable post. Works for Instagram, LinkedIn, and Facebook.",
    promptToGenerate: "Using the 4-part reframe structure, write a cheat codes post about medspa owners who are working hard but not seeing growth. Each section should reframe a common belief they have about why they're stuck. Short sentences, feeling-first language, no em dashes."
  }
];

const CONTENT_TYPES = [
  { id: "instagram", label: "Instagram Caption", emoji: "📸" },
  { id: "linkedin", label: "LinkedIn Post", emoji: "💼" },
  { id: "email", label: "Email", emoji: "✉️" },
  { id: "dm", label: "Sales DM", emoji: "💬" },
  { id: "reel", label: "Reel Script", emoji: "🎬" },
  { id: "story", label: "Story Script", emoji: "📱" },
  { id: "facebook", label: "Facebook Post", emoji: "👥" },
  { id: "followup", label: "Follow-Up Message", emoji: "🔄" },
];

const QUICK_PROMPTS = [
  "Write about why memberships are the most underused revenue tool in medspas",
  "A post about the moment an owner realizes her front desk is leaking revenue",
  "Email to a medspa owner who went quiet after a discovery call",
  "Reel script: 3 signs your medspa is leaving $200K on the table",
  "LinkedIn post about the difference between busy and profitable",
  "DM to a medspa owner who just posted about hitting burnout",
  "Caption for a before/after of a medspa business transformation",
  "Email subject lines for a cold outreach sequence (give me 5)",
];

const CSS = `
  @import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,300;0,400;0,500;0,600;1,300;1,400&family=Montserrat:wght@300;400;500;600&display=swap');
  * { box-sizing: border-box; }
  ::-webkit-scrollbar { width: 4px; }
  ::-webkit-scrollbar-track { background: transparent; }
  ::-webkit-scrollbar-thumb { background: #b8967a44; border-radius: 2px; }
  .fade-in { animation: fadeIn 0.5s ease forwards; }
  @keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }
  .shimmer { background: linear-gradient(90deg, #1e1a28 25%, #2a2438 50%, #1e1a28 75%); background-size: 200% 100%; animation: shimmer 1.5s infinite; border-radius: 4px; }
  @keyframes shimmer { 0% { background-position: 200% 0; } 100% { background-position: -200% 0; } }
  .type-btn { background: transparent; border: 1px solid #2a2438; border-radius: 6px; color: #8a7a9a; padding: 8px 12px; font-family: Montserrat,sans-serif; font-size: 11px; font-weight: 500; letter-spacing: 0.05em; cursor: pointer; transition: all 0.2s; white-space: nowrap; }
  .type-btn:hover { border-color: #b8967a55; color: #c8b4a4; }
  .type-btn.active { background: linear-gradient(135deg,#b8967a22,#d4a87422); border-color: #b8967a; color: #e8c8a8; }
  .main-btn { background: linear-gradient(135deg,#b8967a,#d4a874); border: none; border-radius: 8px; color: #0a0a0f; padding: 14px 28px; font-family: Montserrat,sans-serif; font-size: 12px; font-weight: 600; letter-spacing: 0.12em; text-transform: uppercase; cursor: pointer; transition: all 0.2s; width: 100%; }
  .main-btn:hover { transform: translateY(-1px); box-shadow: 0 8px 24px #b8967a44; }
  .main-btn:disabled { opacity: 0.5; cursor: not-allowed; transform: none; }
  .ghost-btn { background: transparent; border: 1px solid #2a2438; border-radius: 6px; color: #8a7a9a; padding: 8px 16px; font-family: Montserrat,sans-serif; font-size: 11px; font-weight: 500; cursor: pointer; transition: all 0.2s; }
  .ghost-btn:hover { border-color: #b8967a55; color: #c8b4a4; }
  .quick-tag { background: #1a1624; border: 1px solid #2a2438; border-radius: 20px; color: #8a7a9a; padding: 6px 14px; font-family: Montserrat,sans-serif; font-size: 11px; cursor: pointer; transition: all 0.2s; white-space: nowrap; }
  .quick-tag:hover { border-color: #b8967a66; color: #c8b4a4; background: #1e1a2a; }
  .tab-btn { background: transparent; border: none; border-bottom: 2px solid transparent; color: #5a5068; padding: 10px 18px; font-family: Montserrat,sans-serif; font-size: 11px; font-weight: 500; letter-spacing: 0.1em; text-transform: uppercase; cursor: pointer; transition: all 0.2s; }
  .tab-btn.active { color: #b8967a; border-bottom-color: #b8967a; }
  .tab-btn:hover:not(.active) { color: #8a7a9a; }
  .hcard { background: #1a1624; border: 1px solid #2a2438; border-radius: 8px; padding: 14px 16px; cursor: pointer; transition: all 0.2s; margin-bottom: 10px; }
  .hcard:hover { border-color: #b8967a44; }
  .copy-btn { background: #1e1a28; border: 1px solid #2a2438; border-radius: 6px; color: #8a7a9a; padding: 8px 16px; font-family: Montserrat,sans-serif; font-size: 11px; font-weight: 500; cursor: pointer; transition: all 0.2s; }
  .copy-btn:hover { border-color: #b8967a66; color: #c8b4a4; }
  .copy-btn.copied { border-color: #7ab87a; color: #a8d4a8; }
  .pulse { animation: pulse 2s ease-in-out infinite; }
  @keyframes pulse { 0%,100% { opacity:1; } 50% { opacity:0.5; } }
  .swipe-card { background: #12101a; border: 1px solid #2a2438; border-radius: 10px; margin-bottom: 16px; overflow: hidden; }
  .swipe-header { padding: 18px 20px; cursor: pointer; }
  .swipe-body { padding: 20px; border-top: 1px solid #1e1a28; position: relative; }
  .swipe-actions { padding: 14px 20px; border-top: 1px solid #1e1a28; display: flex; gap: 10px; flex-wrap: wrap; }
  .accent-bar { position: absolute; left: 0; top: 0; bottom: 0; width: 2px; background: linear-gradient(180deg,#b8967a,transparent); }
`;

function SwipeCard({ item, generateContent, setPrompt, setSelectedType, setActiveTab }) {
  const [open, setOpen] = useState(false);
  const [copied, setCopied] = useState(false);
  const content = SWIPE_POSTS[item.id] || "";

  function handleCopy() {
    navigator.clipboard.writeText(content);
    setCopied(true);
    setTimeout(function() { setCopied(false); }, 2000);
  }

  function handleGenerate() {
    setPrompt(item.promptToGenerate);
    setSelectedType("instagram");
    setActiveTab("create");
    setTimeout(function() { generateContent(item.promptToGenerate); }, 150);
  }

  return (
    <div className="swipe-card">
      <div className="swipe-header" onClick={function() { setOpen(!open); }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
          <div>
            <div style={{ fontFamily: "Montserrat,sans-serif", fontSize: "11px", fontWeight: 600, letterSpacing: "0.15em", color: "#b8967a", textTransform: "uppercase", marginBottom: "4px" }}>{item.format}</div>
            <div style={{ fontFamily: "Cormorant Garamond,serif", fontSize: "18px", fontWeight: 400, color: "#e8d8c8" }}>{item.label}</div>
          </div>
          <div style={{ color: "#5a5068", fontSize: "16px", marginTop: "4px" }}>{open ? "↑" : "↓"}</div>
        </div>
        <div style={{ fontFamily: "Montserrat,sans-serif", fontSize: "11px", color: "#5a5068", marginTop: "8px", lineHeight: 1.6, fontWeight: 300 }}>{item.note}</div>
      </div>
      {open && (
        <div>
          <div className="swipe-body">
            <div className="accent-bar" />
            <div style={{ fontFamily: "Montserrat,sans-serif", fontSize: "12px", fontWeight: 300, color: "#c8bfb4", whiteSpace: "pre-wrap", lineHeight: 1.8, paddingLeft: "12px" }}>{content}</div>
          </div>
          <div className="swipe-actions">
            <button className={"copy-btn" + (copied ? " copied" : "")} onClick={handleCopy}>{copied ? "✓ Copied" : "Copy Post"}</button>
            <button className="main-btn" style={{ width: "auto", padding: "8px 20px" }} onClick={handleGenerate}>Generate Variation</button>
          </div>
        </div>
      )}
    </div>
  );
}

export default function LuxoraAIStudio() {
  const [selectedType, setSelectedType] = useState("instagram");
