    var msg = "Content type: " + typeObj.label + "\nTopic/Prompt: " + finalPrompt + (context ? "\nAdditional context: " + context : "") + "\n\nWrite this now, ready to use.";
    try {
      var res = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ model: "claude-sonnet-4-20250514", max_tokens: 1000, system: VOICE_SYSTEM_PROMPT, messages: [{ role: "user", content: msg }] })
      });
      var data = await res.json();
      var result = data.content && data.content[0] && data.content[0].text ? data.content[0].text : "Something went wrong. Try again.";
      setOutput(result);
      setHistory(function(prev) {
        return [{ type: typeObj.label, emoji: typeObj.emoji, prompt: finalPrompt, output: result, ts: new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }) }].concat(prev.slice(0, 9));
      });
    } catch (e) {
      setOutput("Connection error. Please try again.");
    }
    setLoading(false);
  }

  useEffect(function() {
    if (output && outputRef.current) outputRef.current.scrollIntoView({ behavior: "smooth", block: "nearest" });
  }, [output]);

  var labelStyle = { fontFamily: "Montserrat,sans-serif", fontSize: "10px", fontWeight: 600, letterSpacing: "0.2em", color: "#5a5068", textTransform: "uppercase", marginBottom: "12px" };
  var monoText = { fontFamily: "Montserrat,sans-serif", fontSize: "12px", color: "#8a7a9a", lineHeight: 1.7, fontWeight: 300 };

  return (
    <div style={{ fontFamily: "Cormorant Garamond,Georgia,serif", minHeight: "100vh", background: "linear-gradient(135deg,#0a0a0f 0%,#12101a 40%,#0d0a14 100%)", color: "#f0ece4" }}>
      <style>{CSS}</style>

      <div style={{ borderBottom: "1px solid #1e1a28", padding: "24px 32px", display: "flex", alignItems: "center", justifyContent: "space-between", position: "sticky", top: 0, background: "rgba(10,10,15,0.95)", backdropFilter: "blur(12px)", zIndex: 100 }}>
        <div>
          <div style={{ fontFamily: "Cormorant Garamond,serif", fontSize: "22px", fontWeight: 300, letterSpacing: "0.15em", color: "#e8d8c8" }}>THE LUXORA COLLECTIVE</div>
          <div style={{ fontFamily: "Montserrat,sans-serif", fontSize: "10px", fontWeight: 500, letterSpacing: "0.25em", color: "#b8967a", textTransform: "uppercase", marginTop: "2px" }}>AI Content Studio · Bethany Anne</div>
        </div>
        <div style={{ width: "8px", height: "8px", borderRadius: "50%", background: "#7ab87a", boxShadow: "0 0 8px #7ab87a88" }} className="pulse" />
      </div>

      <div style={{ maxWidth: "900px", margin: "0 auto", padding: "32px 24px" }}>

        <div style={{ borderBottom: "1px solid #1e1a28", marginBottom: "28px", display: "flex", flexWrap: "wrap" }}>
          <button className={"tab-btn" + (activeTab === "create" ? " active" : "")} onClick={function() { setActiveTab("create"); }}>Create</button>
          <button className={"tab-btn" + (activeTab === "history" ? " active" : "")} onClick={function() { setActiveTab("history"); }}>History {history.length > 0 ? "(" + history.length + ")" : ""}</button>
          <button className={"tab-btn" + (activeTab === "swipe" ? " active" : "")} onClick={function() { setActiveTab("swipe"); }}>Swipe File</button>
          <button className={"tab-btn" + (activeTab === "voice" ? " active" : "")} onClick={function() { setActiveTab("voice"); }}>Voice Guide</button>
        </div>

        {activeTab === "create" && (
          <div className="fade-in">
            <div style={{ marginBottom: "24px" }}>
