              </div>
            )}

            <button className="main-btn" onClick={function() { generateContent(); }} disabled={loading || !prompt.trim()}>
              {loading ? "Writing in your voice..." : "Generate " + (typeObj ? typeObj.label : "")}
            </button>

            <div style={{ marginTop: "28px" }}>
              <div style={Object.assign({}, labelStyle, { color: "#3a3248" })}>Quick Start</div>
              <div style={{ display: "flex", flexWrap: "wrap", gap: "8px" }}>
                {QUICK_PROMPTS.map(function(p, i) {
                  return <button key={i} className="quick-tag" onClick={function() { setPrompt(p); setTimeout(function() { generateContent(p); }, 100); }}>{p.length > 50 ? p.slice(0, 50) + "..." : p}</button>;
                })}
              </div>
            </div>

            {(loading || output) && (
