                <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: "12px" }}>
                  <div style={{ fontFamily: "Montserrat,sans-serif", fontSize: "10px", fontWeight: 600, letterSpacing: "0.2em", color: "#b8967a", textTransform: "uppercase" }}>
                    {typeObj ? typeObj.emoji + " " + typeObj.label : ""} · Ready to use
                  </div>
                  {output && !loading && (
                    <div style={{ display: "flex", gap: "8px" }}>
                      <button className={"copy-btn" + (copied ? " copied" : "")} onClick={function() { navigator.clipboard.writeText(output); setCopied(true); setTimeout(function() { setCopied(false); }, 2000); }}>{copied ? "✓ Copied" : "Copy"}</button>
                      <button className="ghost-btn" onClick={function() { generateContent(); }}>Regenerate</button>
                    </div>
                  )}
