import { useState, useRef, useEffect } from "react";

const SYSTEM_PROMPT = [
  "You are Bethany Anne's personal AI content writer for The Luxora Collective.",
  "You write growth content that sounds EXACTLY like her: not like an AI, not like a corporate consultant, like a trusted peer who happens to be brilliant at medspa business strategy.",
  "",
  "WHO YOU ARE WRITING FOR (Dream Client):",
  "Independent medspa owner, usually a woman, generating $500K-$3M/year.",
  "She is talented, hardworking, maybe a bit overwhelmed.",
  "She KNOWS she could be doing more but does not know exactly what is missing.",
  "She cares deeply about her clients, her team, her brand.",
  "She is probably leaving $200K-$500K on the table in retention, packages, and follow-up.",
  "She is NOT a marketing person. She is a clinician who became a business owner.",
  "She responds to warmth, specificity, and peer energy. Not hype, not pressure.",
  "",
  "BETHANY ANNE VOICE RULES:",
  "1. Write like you are talking to a smart friend over coffee: warm, real, direct.",
  "2. Start with the feeling, not the feature. Lead with what she is experiencing, not what you offer.",
  "3. Use short sentences. Break things up. White space is your friend.",
  "4. No corporate speak. No synergies, no leverage, no robust solutions.",
  "5. No em dashes. Use commas, colons, or rewrite the sentence instead.",
  "6. Be specific. $200K in walk-away revenue hits harder than significant revenue loss.",
  "7. Permission-based and feminine in energy. Never pushy, never bro-ish.",
  "8. You can be a little bold, a little wry. Confidence without arrogance.",
  "9. Call her IN, not out. You are pulling her forward, not pointing at what she is doing wrong.",
  "10. Reference real medspa scenarios: memberships, Botox retention, package upsells, front desk gaps, no-show patterns, lapsed clients, staff culture.",
  "",
  "WHAT LUXORA SELLS:",
  "The 90-Day Growth Engine: installs membership programs, package architecture, upsell frameworks, AI-powered follow-up, staff training, and marketing execution.",
  "For medspas doing $500K-$3M/year.",
  "Financing available via Klarna and Affirm.",
  "Results: more recurring revenue, higher LTV, better client retention, less owner burnout.",
  "Referral partner: Tracy Olson / Aesthetic Injector Academy (injectorsschool.com).",
  "",
  "TONE BY FORMAT:",
  "Instagram: shorter, emotional, I see you energy.",
  "LinkedIn: slightly broader but still medspa-specific and human.",
  "Email: warmest, most personal, like she is writing to one person.",
  "DM: ultra-casual, brief, no pitch in first message.",
  "Reel script: pattern interrupt in line 1, value in 15 seconds, CTA.",
  "",
  "Always deliver the content clean and ready to use. No preamble. No 'Here is your caption:' prefix. Just the content. If you have a brief note like a suggested hook variant, put it after the main content separated by a blank line and two dashes."
].join("\n");

const SWIPE_CONTENT = {
  cheatcodes: [
    "Gifting you the revenue cheat codes nobody talks about at medspa conferences.",
    "",
    "Save this. You will want to come back to it.",
    "",
    "1. Your retention problem is not really a retention problem. It is a follow-up gap.",
    "Your clients are not leaving because they stopped caring.",
    "They are leaving because nobody reached out between appointments.",
    "The medspa that follows up wins. Every time.",
    "When your system does it automatically, your revenue stops being seasonal.",
    "",
    "2. You do not have a slow month problem. You have a membership problem.",
    "Most owners wait for January to panic about revenue.",
    "The ones who do not panic? They built recurring income before they needed it.",
    "A membership program does not just smooth out cash flow.",
    "It changes how your clients think about your spa. They stop being visitors. They become members.",
    "",
    "3. Your front desk is not underperforming. She is undertrained on what to say after yes.",
    "She knows how to book an appointment.",
    "She does not know how to turn a single Botox visit into a skincare package and a membership.",
    "That is not her fault. That is a training and script gap.",
    "Fix the script, and your front desk becomes your highest-converting sales tool.",
    "",
    "4. You do not have an audience problem. You have a recognition problem. And they are not the same thing.",
    "The right client can drive past your medspa every single day and never come in.",
    "Not because she does not need you.",
    "Because she has not yet recognized herself in what you are saying.",
    "When she does, she does not just book once. She refers everyone she knows.",
    "",
    "Which one hit closest to home? Drop a comment if you felt this."
  ].join("\n"),
  framework: [
    "THE 4-PART REFRAME STRUCTURE",
    "",
    "Opening line: Gifting you the [X] cheat codes...",
    "Save prompt: Save this. You will want to come back to it.",
    "",
    "Each section follows this pattern:",
    "- Numbered (1, 2, 3, 4)",
    "- Quotable one-liner: this is the reframe. Make it bold and specific.",
    "- 3-4 short sentences that expand the FEELING, not the logic.",
    "- Sentences should make her feel seen, not lectured.",
    "- End with a forward pull: when X happens, Y changes.",
    "",
    "Closing CTA: Soft, conversational, invites engagement.",
    "Example: Which one hit closest? Drop a comment if you felt this.",
    "",
    "RULES:",
    "- Each one-liner must be a reframe, not a tip.",
    "- Never explain the offer in the post.",
    "- Lead with her experience, not your solution.",
    "- The reader should feel like you wrote this for her alone.",
    "- Short sentences. White space. No em dashes."
  ].join("\n")
};

const SWIPE_FILE = [
  {
    id: "cheatcodes",
    label: "Medspa Revenue Cheat Codes",
    format: "Instagram / LinkedIn",
    note: "4-part reframe post adapted from a viral coaching structure. Each section opens with a bold reframe, followed by 3-4 feeling-first sentences. Ends with soft CTA.",
    generatePrompt: "Write a brand new 4-part medspa revenue cheat codes post. Use this exact structure: numbered sections, each opening with a quotable reframe one-liner in quotes, followed by 3-4 short feeling-first sentences. End with a soft engagement CTA. Pick 4 different revenue gaps than: follow-up gap, membership gap, front desk training gap, recognition problem. Short sentences, no em dashes, write in Bethany Anne voice."
  },
  {
    id: "framework",
    label: "The 4-Part Reframe Framework",
    format: "Content Structure Guide",
    note: "The structural blueprint behind the cheat codes post. Use this any time you want a high-engagement saveable post for Instagram, LinkedIn, or Facebook.",
    generatePrompt: "Using the 4-part reframe structure, write a cheat codes post for medspa owners who are working hard but not seeing growth. Each section reframes a belief they have about why they are stuck. Short sentences, feeling-first, no em dashes, Bethany Anne voice."
  }
];

const CONTENT_TYPES = [
  { id: "instagram", label: "Instagram Caption", emoji: "📸" },
  { id: "linkedin", label: "LinkedIn Post", emoji: "💼" },
  { id: "email", label: "Email", emoji: "✉️" },
  { id: "dm", label: "Sales DM", emoji: "💬" },
  { id: "reel", label: "Reel Script", emoji: "🎬" },
  { id: "story", label: "Story Script", emoji: "📱" },
  { id: "facebook", label: "Facebook Post", emoji: "👥" },
  { id: "followup", label: "Follow-Up Message", emoji: "🔄" }
];

const QUICK_PROMPTS = [
  "Why memberships are the most underused revenue tool in medspas",
