function SwipeCard({ item, onGenerate }) {
  const [open, setOpen] = useState(false);
  const [copied, setCopied] = useState(false);
  const content = SWIPE_CONTENT[item.id] || "";

  function doCopy() {
    navigator.clipboard.writeText(content);
    setCopied(true);
    setTimeout(function() { setCopied(false); }, 2000);
  }

  return (
    <div style={{ background: "#12101a", border: "1px solid #2a2438", borderRadius: "10px", marginBottom: "16px", overflow: "hidden" }}>
      <div
        onClick={function() { setOpen(function(v) { return !v; }); }}
        style={{ padding: "20px", cursor: "pointer", borderBottom: open ? "1px solid #1e1a28" : "none" }}
      >
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
          <div style={{ flex: 1 }}>
            <div style={{ fontFamily: "'Montserrat', sans-serif", fontSize: "10px", fontWeight: 600, letterSpacing: "0.2em", color: "#b8967a", textTransform: "uppercase", marginBottom: "5px" }}>
              {item.format}
            </div>
            <div style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: "20px", fontWeight: 400, color: "#e8d8c8", lineHeight: 1.3 }}>
              {item.label}
            </div>
          </div>
          <div style={{ color: "#5a5068", fontSize: "18px", marginLeft: "12px", marginTop: "2px", transition: "transform 0.2s", transform: open ? "rotate(180deg)" : "rotate(0deg)" }}>
            ↓
          </div>
        </div>
        <div style={{ fontFamily: "'Montserrat', sans-serif", fontSize: "11px", color: "#5a5068", marginTop: "10px", lineHeight: 1.6, fontWeight: 300 }}>
          {item.note}
        </div>
      </div>

      {open && (
        <div>
          <div style={{ padding: "22px 22px 22px 32px", borderBottom: "1px solid #1e1a28", position: "relative" }}>
            <div style={{ position: "absolute", left: 0, top: 0, bottom: 0, width: "3px", background: "linear-gradient(180deg, #b8967a 0%, transparent 100%)", borderRadius: "0 0 0 10px" }} />
            <div style={{ fontFamily: "'Montserrat', sans-serif", fontSize: "12px", fontWeight: 300, color: "#c8bfb4", whiteSpace: "pre-wrap", lineHeight: 1.9 }}>
              {content}
            </div>
          </div>
          <div style={{ padding: "14px 20px", display: "flex", gap: "10px", alignItems: "center", flexWrap: "wrap" }}>
            <button
              onClick={doCopy}
              style={{ background: copied ? "#1a2a1a" : "#1e1a28", border: copied ? "1px solid #7ab87a" : "1px solid #2a2438", borderRadius: "6px", color: copied ? "#a8d4a8" : "#8a7a9a", padding: "8px 18px", fontFamily: "'Montserrat', sans-serif", fontSize: "11px", fontWeight: 500, cursor: "pointer", transition: "all 0.2s" }}
            >
              {copied ? "✓ Copied" : "Copy Post"}
            </button>
            <button
              onClick={function() { onGenerate(item.generatePrompt); }}
              style={{ background: "linear-gradient(135deg, #b8967a, #d4a874)", border: "none", borderRadius: "6px", color: "#0a0a0f", padding: "8px 18px", fontFamily: "'Montserrat', sans-serif", fontSize: "11px", fontWeight: 600, letterSpacing: "0.1em", textTransform: "uppercase", cursor: "pointer", transition: "all 0.2s" }}
            >
              Generate Variation
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

export default function App() {
  const [tab, setTab] = useState("create");
  const [formatId, setFormatId] = useState("instagram");
  const [prompt, setPrompt] = useState("");
  const [context, setContext] = useState("");
  const [showCtx, setShowCtx] = useState(false);
  const [output, setOutput] = useState("");
  const [loading, setLoading] = useState(false);
  const [copied, setCopied] = useState(false);
  const [history, setHistory] = useState([]);
  const outputRef = useRef(null);
  const fmt = CONTENT_TYPES.find(function(t) { return t.id === formatId; });

  async function generate(overridePrompt) {
    var p = overridePrompt || prompt;
    if (!p || !p.trim()) return;
    setLoading(true);
    setOutput("");
    setTab("create");
    var userMsg = "Content type: " + fmt.label + "\nTopic: " + p + (context ? "\nExtra context: " + context : "") + "\n\nWrite this now, ready to use.";
    try {
      var res = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          model: "claude-sonnet-4-20250514",
          max_tokens: 1000,
          system: SYSTEM_PROMPT,
          messages: [{ role: "user", content: userMsg }]
        })
      });
      var data = await res.json();
      var text = data.content && data.content[0] ? data.content[0].text : "Something went wrong. Please try again.";
      setOutput(text);
      setHistory(function(prev) {
        return [{
          type: fmt.label,
          emoji: fmt.emoji,
          prompt: p,
          output: text,
          time: new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })
        }].concat(prev.slice(0, 9));
      });
    } catch (err) {
      setOutput("Connection error. Please try again.");
    }
    setLoading(false);
  }

  function handleSwipeGenerate(genPrompt) {
    setPrompt(genPrompt);
    setFormatId("instagram");
    setTab("create");
    setTimeout(function() { generate(genPrompt); }, 80);
  }

  useEffect(function() {
    if (output && outputRef.current) {
