        @import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,300;0,400;0,500;0,600;1,300;1,400&family=Montserrat:wght@300;400;500;600&display=swap');
        * { box-sizing: border-box; margin: 0; padding: 0; }
        ::-webkit-scrollbar { width: 4px; }
        ::-webkit-scrollbar-track { background: transparent; }
        ::-webkit-scrollbar-thumb { background: #b8967a44; border-radius: 2px; }
        @keyframes fadeUp { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
        @keyframes shimmer { 0% { background-position: 200% 0; } 100% { background-position: -200% 0; } }
        @keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.4; } }
        .fade-up { animation: fadeUp 0.4s ease forwards; }
        .pulse-dot { animation: pulse 2s ease-in-out infinite; }
        .shimmer-line { background: linear-gradient(90deg, #1e1a28 25%, #2d2540 50%, #1e1a28 75%); background-size: 200% 100%; animation: shimmer 1.6s ease infinite; border-radius: 4px; }
        .fmt-btn { background: transparent; border: 1px solid #221e2e; border-radius: 8px; color: #6a5c7a; padding: 9px 14px; font-family: 'Montserrat', sans-serif; font-size: 11px; font-weight: 500; letter-spacing: 0.04em; cursor: pointer; transition: all 0.25s; white-space: nowrap; }
        .fmt-btn:hover { border-color: #b8967a66; color: #c8b4a4; background: #16121e; }
