                    </div>
                    <div style={{ fontFamily: mono, fontSize: "12px", color: "#7a6a8a", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap", marginBottom: "6px" }}>
                      {item.prompt}
